CREATE TABLE IF NOT EXISTS governance_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_code text UNIQUE NOT NULL, title text NOT NULL, document_type text NOT NULL, version text NOT NULL DEFAULT '1.0', status text NOT NULL DEFAULT 'Draft', effective_date date, owner_role text, summary text, content text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS authority_matrix (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_name text NOT NULL, authority_area text NOT NULL, authority_level text NOT NULL, approval_limit numeric, conditions text, status text NOT NULL DEFAULT 'Active', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS corporate_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resolution_number text UNIQUE NOT NULL, resolution_type text NOT NULL, title text NOT NULL, proposed_date date NOT NULL DEFAULT CURRENT_DATE, effective_date date, status text NOT NULL DEFAULT 'Draft', decision_summary text, supporting_document text, recorded_by text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS governance_documents_status_idx ON governance_documents(status);
CREATE INDEX IF NOT EXISTS authority_matrix_role_idx ON authority_matrix(role_name);
CREATE INDEX IF NOT EXISTS resolutions_status_idx ON corporate_resolutions(status);